-- 0105 — As fronteiras dos concelhos entram na base.
--
-- O contorno de cada concelho vivia num módulo TypeScript gerado
-- (`apps/web/src/lib/fronteiras.ts`) — dezanove quilobytes de geografia de UM
-- inquilino dentro do código do produto. Passa a coluna: `boundary` é o anel
-- exterior do concelho, um array JSON de pares [longitude, latitude], fechado
-- (o último par igual ao primeiro), com quatro casas decimais — cerca de onze
-- metros, menos de um pixel num mapa de cinquenta quilómetros.
--
-- Os dados são exatamente os que o repositório já tinha: vieram do
-- OpenStreetMap pelo Nominatim, simplificados a 0,002°, e cada polígono foi
-- confrontado com a área oficial do concelho (Carta Administrativa Oficial de
-- Portugal) antes de entrar — é essa conta, feita por
-- `scripts/buscar-fronteiras.py` na geração, que prova que veio a fronteira
-- do concelho e não a da cidade homónima. Para os refrescar, ou para uma
-- região nova, corre-se o script, que hoje emite uma migração como esta.
--
-- Anulável de propósito: uma região pode nascer sem contornos e o mapa
-- degrada para os centros dos concelhos, como o código sempre fez quando
-- lhe faltava uma fronteira.
--
-- Dados © contribuidores do OpenStreetMap, ODbL 1.0 — https://osm.org/copyright

alter table public.municipalities
  add column boundary jsonb;

comment on column public.municipalities.boundary is
  'O anel exterior do concelho: array JSON de pares [longitude, latitude], '
  'fechado, com ~4 casas decimais. Gerado por scripts/buscar-fronteiras.py a '
  'partir do OpenStreetMap (Nominatim) e confrontado com a área oficial do '
  'concelho antes de entrar. Dados © contribuidores do OpenStreetMap, ODbL '
  '1.0 (https://osm.org/copyright). Anulável: sem contorno, o mapa degrada '
  'para o centro do concelho.';

