-- ---------------------------------------------------------------------------
-- A rede de segurança: os anéis são anéis, e cabem na região a que pertencem.
-- A caixa da região é para centros e espaços; um contorno roça mais largo —
-- daí a folga de um décimo de grau, uns onze quilómetros.
do $$
declare
  v_n integer;
begin
  select count(*) into v_n
  from public.municipalities
  where region_id = 'medio-tejo' and boundary is null;
  if v_n <> 0 then
    raise exception '% concelhos do Médio Tejo ficaram sem fronteira', v_n;
  end if;

  select count(*) into v_n
  from public.municipalities
  where boundary is not null
    and (jsonb_typeof(boundary) <> 'array' or jsonb_array_length(boundary) < 4);
  if v_n <> 0 then
    raise exception '% fronteiras que não são um anel', v_n;
  end if;

  select count(*) into v_n
  from public.municipalities
  where boundary is not null
    and boundary -> 0 is distinct from boundary -> (jsonb_array_length(boundary) - 1);
  if v_n <> 0 then
    raise exception '% anéis por fechar', v_n;
  end if;

  select count(*) into v_n
  from public.municipalities m
  join public.regions r on r.id = m.region_id
  cross join lateral jsonb_array_elements(m.boundary) as ponto
  where m.boundary is not null
    and ((ponto ->> 0)::double precision not between r.bbox_lon_min - 0.1 and r.bbox_lon_max + 0.1
      or (ponto ->> 1)::double precision not between r.bbox_lat_min - 0.1 and r.bbox_lat_max + 0.1);
  if v_n <> 0 then
    raise exception '% vértices de fronteira fora da caixa da sua região', v_n;
  end if;
end $$;
